package com.aitu.lms;
import com.aitu.lms.domain.*; import com.aitu.lms.integration.*; import com.aitu.lms.observer.*; import com.aitu.lms.visitor.*;
import org.junit.jupiter.api.*; import java.time.Instant; import java.util.concurrent.*; import java.util.concurrent.atomic.AtomicInteger;
import static org.junit.jupiter.api.Assertions.*;
class UniversityLmsTest {
 @Test void eventIsImmutable(){var e=new Event(EventType.GRADE_CHANGED,"S1","x",Instant.now());assertEquals("S1",e.studentId());}
 @Test void subscribeReceivesMatchingType(){try(var s=new ThreadSafeSubject(2)){var r=new RecordingListener("x");s.subscribe(EventType.GRADE_CHANGED,r);s.publish(new Event(EventType.GRADE_CHANGED,"S1","x",Instant.now()));s.shutdownGracefully();assertEquals(1,r.count());}}
 @Test void wrongTypeIsIgnored(){try(var s=new ThreadSafeSubject(2)){var r=new RecordingListener("x");s.subscribe(EventType.GRADE_CHANGED,r);s.publish(new Event(EventType.DEADLINE_UPDATED,"S1","x",Instant.now()));s.shutdownGracefully();assertEquals(0,r.count());}}
 @Test void unsubscribeWorks(){try(var s=new ThreadSafeSubject(2)){var r=new RecordingListener("x");s.subscribe(EventType.GRADE_CHANGED,r);s.unsubscribe(EventType.GRADE_CHANGED,r);s.publish(new Event(EventType.GRADE_CHANGED,"S1","x",Instant.now()));s.shutdownGracefully();assertEquals(0,r.count());}}
 @Test void duplicateSubscriptionDoesNotDuplicate(){try(var s=new ThreadSafeSubject(2)){var r=new RecordingListener("x");s.subscribe(EventType.GRADE_CHANGED,r);s.subscribe(EventType.GRADE_CHANGED,r);s.publish(new Event(EventType.GRADE_CHANGED,"S1","x",Instant.now()));s.shutdownGracefully();assertEquals(1,r.count());}}
 @Test void gpaTrackerAggregatesPerStudent(){var g=new GpaTracker();g.onEvent(new Event(EventType.GRADE_CHANGED,"S1","a",Instant.now()));g.onEvent(new Event(EventType.GRADE_CHANGED,"S1","b",Instant.now()));assertEquals(2,g.changesFor("S1"));}
 @Test void aggregatorRepublishes(){try(var s=new ThreadSafeSubject(2)){var a=new AggregatingListener(s);var r=new RecordingListener("gpa");s.subscribe(EventType.GPA_UPDATED,r);a.onEvent(new Event(EventType.GRADE_CHANGED,"S1","a",Instant.now()));s.shutdownGracefully();assertEquals(1,a.aggregateCount());assertEquals(1,r.count());}}
 @Test void creditsAreCalculated(){var f=tree();assertEquals(9,f.accept(new CreditVisitor()));}
 @Test void workloadIsCalculated(){var f=tree();assertEquals(19,f.accept(new WorkloadVisitor()));}
 @Test void filterReturnsStudents(){var f=tree();assertEquals(1,f.accept(new StudentFilterVisitor(3.2)).size());}
 @Test void jsonHasNesting(){var f=tree();var json=f.accept(new JsonExportVisitor());assertTrue(json.contains("School of Software Engineering"));assertTrue(json.contains("Algorithms"));assertTrue(json.contains("Union Find"));}
 @Test void doubleDispatchUsesConcreteElement(){var f=tree();var v=new Visitor<String>(){public String visitFaculty(Faculty x){return "faculty";}public String visitProgram(Program x){return "program";}public String visitCourse(Course x){return "course";}public String visitLecture(Lecture x){return "lecture";}public String visitLab(Lab x){return "lab";}public String visitExam(Exam x){return "exam";}public String visitStudent(Student x){return "student";}};assertEquals("faculty",f.accept(v));}
 @Test void integrationInspectsRelatedSubtree(){try(var s=new ThreadSafeSubject(2)){var f=tree();var listener=new AlertInspectionListener(s,f);listener.onEvent(new Event(EventType.ALERT,"S1","alert",Instant.now()));assertNotNull(listener.lastReport());assertEquals(9,listener.lastReport().credits());assertEquals(19,listener.lastReport().workload());s.shutdownGracefully();}}
 @Test void threeProducerThreadsPublish(){try(var s=new ThreadSafeSubject(4)){var r=new RecordingListener("x");s.subscribe(EventType.GRADE_CHANGED,r);var pool=Executors.newFixedThreadPool(3);for(int i=0;i<3;i++)pool.submit(()->{for(int j=0;j<100;j++)s.publish(new Event(EventType.GRADE_CHANGED,"S","x",Instant.now()));});pool.shutdown();assertTrue(pool.awaitTermination(5,TimeUnit.SECONDS));s.shutdownGracefully();assertEquals(300,r.count());}}
 @Test void unsubscribeInsideHandlerIsSafe(){try(var s=new ThreadSafeSubject(2)){var count=new AtomicInteger();Observer[] box=new Observer[1];box[0]=e->{count.incrementAndGet();s.unsubscribe(EventType.GRADE_CHANGED,box[0]);};s.subscribe(EventType.GRADE_CHANGED,box[0]);s.publish(new Event(EventType.GRADE_CHANGED,"S","1",Instant.now()));s.publish(new Event(EventType.GRADE_CHANGED,"S","2",Instant.now()));s.shutdownGracefully();assertEquals(1,count.get());}}
 @Test void stressFourThreadsFourThousandEvents(){try(var s=new ThreadSafeSubject(8)){var r=new RecordingListener("stress");s.subscribe(EventType.GRADE_CHANGED,r);var pool=Executors.newFixedThreadPool(4);for(int i=0;i<4;i++)pool.submit(()->{for(int j=0;j<1000;j++)s.publish(new Event(EventType.GRADE_CHANGED,"S","x",Instant.now()));});pool.shutdown();assertTrue(pool.awaitTermination(10,TimeUnit.SECONDS));s.shutdownGracefully();assertEquals(4000,r.count());}}
 @Test void closedSubjectRejectsPublishing(){var s=new ThreadSafeSubject(1);s.shutdownGracefully();assertThrows(IllegalStateException.class,()->s.publish(new Event(EventType.GRADE_CHANGED,"S","x",Instant.now())));}
 private Faculty tree(){var f=new Faculty("School of Software Engineering");var p=new Program("Software Engineering");var c=new Course("Algorithms",5);c.add(new Lecture("Graphs",4));c.add(new Lab("Union Find",3));c.add(new Exam("Final Exam",2));c.add(new Student("S1","Aruzhan",3.4));var c2=new Course("OS",4);c2.add(new Lecture("Processes",4));c2.add(new Lab("Linux",3));c2.add(new Exam("OS Final",2));c2.add(new Student("S2","Student",3.0));p.add(c);p.add(c2);f.add(p);return f;}
}
